// B1 (familiarcow 2026-11-11: "show the prompts"): copies the AI judge's prompt text out of the resolver's Rust source, byte for byte,
// into lib/judgePrompt.generated.ts, so the bet page's "AI judge" section shows the same words the resolver sends.
// Sources: resolver/core/src/lib.rs (FIXED_SYSTEM, CLAUSES, NOW_SENTENCE, build_messages_at's format strings) and
// resolver/wasm-bin/src/template_audit.rs (the typed-template audit prompt). tests/judgePrompt.unit.test.ts fails when the
// generated file is stale. Run: npx tsx scripts/genJudgePrompt.ts
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..", "..", "..");
export const CORE = join(ROOT, "resolver/core/src/lib.rs");
export const AUDIT = join(ROOT, "resolver/wasm-bin/src/template_audit.rs");
export const OUT = join(ROOT, "apps/web/lib/judgePrompt.generated.ts");

/** The body of a Rust "..." literal starting at `i` (the opening quote), unescaped. */
function rustString(src: string, i: number): { value: string; end: number } {
  if (src[i] !== '"') throw new Error(`expected a string literal at ${i}`);
  let out = "";
  let j = i + 1;
  for (;;) {
    const c = src[j];
    if (c === undefined) throw new Error("unterminated string literal");
    if (c === '"') return { value: out, end: j + 1 };
    if (c === "\\") {
      const n = src[j + 1];
      if (n === "n") out += "\n";
      else if (n === "t") out += "\t";
      else if (n === "r") out += "\r";
      else if (n === "0") out += "\0";
      else if (n === '"' || n === "\\" || n === "'") out += n;
      else if (n === "u") {
        const m = /^\{([0-9a-fA-F]+)\}/.exec(src.slice(j + 2));
        if (!m) throw new Error("bad \\u escape");
        out += String.fromCodePoint(parseInt(m[1], 16));
        j += m[0].length;
      } else if (n === "\n") {
        // line continuation: skip the newline and leading whitespace
        j += 2;
        while (/\s/.test(src[j])) j++;
        continue;
      } else throw new Error(`unknown escape \\${n}`);
      j += 2;
      continue;
    }
    out += c;
    j++;
  }
}

/** The first string literal after `marker`. */
function literalAfter(src: string, marker: string): string {
  const at = src.indexOf(marker);
  if (at < 0) throw new Error(`marker not found: ${marker}`);
  return rustString(src, src.indexOf('"', at + marker.length)).value;
}

export function extract(core: string, audit: string) {
  const clauses: Record<string, string> = {};
  const start = core.indexOf("pub static CLAUSES");
  const stop = core.indexOf("});", start);
  const block = core.slice(start, stop);
  const re = /m\.insert\(/g;
  let m: RegExpExecArray | null;
  while ((m = re.exec(block))) {
    const k = rustString(block, block.indexOf('"', m.index));
    const v = rustString(block, block.indexOf('"', k.end));
    clauses[k.value] = v.value;
  }
  const bm = core.indexOf("pub fn build_messages_at");
  const body = core.slice(bm);
  return {
    FIXED_SYSTEM: literalAfter(core, "pub const FIXED_SYSTEM: &str = "),
    NOW_SENTENCE: literalAfter(core, "pub const NOW_SENTENCE: &str = "),
    CLAUSES: clauses,
    RULES_FORMAT: literalAfter(body, "let mut rules = format!("),
    RESOLUTION_TIME_FORMAT: literalAfter(body, "rules.push_str(&format!("),
    EXHIBIT_FORMAT: literalAfter(body, "blocks.push(format!("),
    USER_FORMAT: literalAfter(body, "let user = format!("),
    AUDIT_SYSTEM: literalAfter(audit, '("system".to_string(), '),
    AUDIT_USER_FORMAT: literalAfter(audit, '("user".to_string(), format!('),
  };
}

export function render(core: string, audit: string): string {
  const x = extract(core, audit);
  const lines = [
    "// GENERATED by scripts/genJudgePrompt.ts from resolver/core/src/lib.rs and resolver/wasm-bin/src/template_audit.rs. Do not edit;",
    "// re-run `npx tsx scripts/genJudgePrompt.ts` (tests/judgePrompt.unit.test.ts fails while this is stale). Rust format strings keep",
    "// their `{}` / `{r}` placeholders; lib/judgePrompt.ts fills them exactly as the Rust code does.",
    ...Object.entries(x).map(([k, v]) => `export const ${k} = ${JSON.stringify(v, null, k === "CLAUSES" ? 2 : undefined)}${k === "CLAUSES" ? " as Record<string, string>" : ""};`),
    "",
  ];
  return lines.join("\n");
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  writeFileSync(OUT, render(readFileSync(CORE, "utf8"), readFileSync(AUDIT, "utf8")));
  console.log(`wrote ${OUT}`);
}
